// ─── File: HotRowDemo.java ───
// Runnable demo: sharded counter and buffered counter vs one hot row.
package com.bank.hotrow;

import java.util.concurrent.*;
import java.util.logging.*;

public class HotRowDemo {

    private static final Logger log = Logger.getLogger("HotRow");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        int increments = 10_000;

        // Sharded counter: writers spread across 16 sub-rows.
        ShardedCounter sharded = new ShardedCounter("fd_opened_today", 16);
        runConcurrent(increments, sharded::increment);
        log.info(() -> "SHARDED total = " + sharded.total() + " (expected " + increments + ")");

        // Buffered counter: increment in Redis-like store, flush to DB periodically.
        BufferedCounter buffered = new BufferedCounter("post_likes");
        buffered.startFlusher(200);  // flush every 200ms
        runConcurrent(increments, buffered::increment);
        buffered.flushNow();
        buffered.stopFlusher();
        log.info(() -> "BUFFERED db value = " + buffered.dbValue()
                + " (expected " + increments + ")");
    }

    static void runConcurrent(int n, Runnable op) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(32);
        CountDownLatch gate = new CountDownLatch(1);
        for (int i = 0; i < n; i++) {
            pool.submit(() -> { try { gate.await(); } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); } op.run(); });
        }
        gate.countDown();
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);
    }
}

// ─── naive/HotCounter.java (the PROBLEM: one contended row) ───
class HotCounter {
    private long value;   // one row; every increment serializes on this lock
    synchronized void increment() { value++; }   // simulates row lock contention
    synchronized long value() { return value; }
}

// ─── shard/ShardedCounter.java (split into N sub-counters, sum on read) ───
class ShardedCounter {
    private final String counterId;
    private final java.util.concurrent.atomic.AtomicLongArray shards;
    private final int n;
    ShardedCounter(String counterId, int n) {
        this.counterId = counterId; this.n = n;
        this.shards = new java.util.concurrent.atomic.AtomicLongArray(n);
    }
    // Writer picks a shard → spreads contention across N locks/rows.
    void increment() {
        int shard = ThreadLocalRandom.current().nextInt(n);
        shards.incrementAndGet(shard);   // simulates UPDATE shard[i] SET v=v+1
    }
    // Read = SUM over all shards.
    long total() {
        long sum = 0;
        for (int i = 0; i < n; i++) sum += shards.get(i);
        return sum;
    }
}

// ─── buffer/BufferedCounter.java (Redis buffer + periodic DB flush) ───
class BufferedCounter {
    private static final Logger log = Logger.getLogger("HotRow");
    private final String key;
    private final java.util.concurrent.atomic.AtomicLong redisBuffer =
            new java.util.concurrent.atomic.AtomicLong();   // Redis INCR
    private final java.util.concurrent.atomic.AtomicLong dbValue =
            new java.util.concurrent.atomic.AtomicLong();   // DB counter row
    private ScheduledExecutorService flusher;
    BufferedCounter(String key) { this.key = key; }

    // Extremely fast in-memory increment (Redis INCR on one key).
    void increment() { redisBuffer.incrementAndGet(); }

    // Periodically move the accumulated delta into the DB in ONE batched write.
    void startFlusher(long ms) {
        flusher = Executors.newSingleThreadScheduledExecutor();
        flusher.scheduleAtFixedRate(this::flushNow, ms, ms, TimeUnit.MILLISECONDS);
    }
    void flushNow() {
        long delta = redisBuffer.getAndSet(0);   // atomically take + reset buffer
        if (delta > 0) {
            dbValue.addAndGet(delta);             // UPDATE counter SET v=v+delta
            log.info(() -> "FLUSH +" + delta + " to DB for " + key
                    + " → " + dbValue.get());
        }
    }
    void stopFlusher() { if (flusher != null) flusher.shutdownNow(); }
    long dbValue() { return dbValue.get(); }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
